  // library/boardguide.js
  "Logique": "Logic level",
  "Carte": "Board",
  "Ajouter": "Add",
  "Débutant": "Beginner",
  "≈ 4 000 – 8 000 FCFA (clone)": "≈ 4,000 – 8,000 FCFA (clone)",
  "Apprendre : LED, boutons, capteurs, moteurs. Le premier choix d’un club ou d’une salle de TP.": "Learning: LEDs, buttons, sensors, motors. The first choice for a club or a lab room.",
  "≈ 3 000 – 6 000 FCFA (clone)": "≈ 3,000 – 6,000 FCFA (clone)",
  "La même carte que l’Uno, en petit : se pique directement sur la breadboard, idéale pour un montage définitif.": "The same board as the Uno, smaller: it plugs straight into the breadboard, ideal for a permanent build.",
  "Intermédiaire": "Intermediate",
  "≈ 5 000 – 9 000 FCFA": "≈ 5,000 – 9,000 FCFA",
  "Objets connectés : station météo en ligne, arrosage commandé par téléphone, serveur web. Plus rapide, mais logique 3,3 V.": "Connected devices: online weather station, phone-controlled irrigation, web server. Faster, but 3.3 V logic.",
  "≈ 3 500 – 6 000 FCFA": "≈ 3,500 – 6,000 FCFA",
  "Le Wi-Fi le moins cher : un capteur qui envoie ses mesures. Une seule entrée analogique.": "The cheapest Wi-Fi: a sensor that sends its readings. Only one analog input.",
  "≈ 4 000 – 7 000 FCFA": "≈ 4,000 – 7,000 FCFA",
  "Apprendre MicroPython ; signaux très précis (rubans de LED) grâce à ses blocs PIO. Version « W » avec Wi-Fi.": "Learning MicroPython; very precise signals (LED strips) thanks to its PIO blocks. “W” version with Wi-Fi.",
  "{0} bits": "{0} bits",
  "Fiche": "Sheet",
  "Guide": "Guide",
  "Quelle carte choisir ?": "Which board should I choose?",
  "Les cartes simulées par Jollof Studio, comparées pour un club, une salle de TP ou un projet : ce qu’elles savent faire, leurs pièges, par laquelle commencer.": "The boards Jollof Studio simulates, compared for a club, a lab room or a project: what they can do, their pitfalls, which one to start with.",
  "Microcontrôleur ou ordinateur monocarte ?": "Microcontroller or single-board computer?",
  "Un **microcontrôleur** (Arduino, ESP32, Pico) exécute un seul programme, celui que vous téléversez, dès qu’il est alimenté : il réagit vite et toujours de la même façon. C’est lui qui allume une LED, lit un capteur, commande un moteur. Jollof Studio simule les microcontrôleurs.": "A **microcontroller** (Arduino, ESP32, Pico) runs a single program, the one you upload, as soon as it is powered: it reacts fast and always the same way. It is what turns on an LED, reads a sensor, drives a motor. Jollof Studio simulates microcontrollers.",
  "Un **ordinateur monocarte** (Raspberry Pi 4 ou 5…) est un petit ordinateur complet sous Linux : écran, clavier, Internet, fichiers, caméra. Il sert quand il faut traiter des images ou héberger un serveur, et confie souvent les signaux précis à un microcontrôleur.": "A **single-board computer** (Raspberry Pi 4 or 5…) is a small complete computer running Linux: screen, keyboard, Internet, files, camera. It is useful for processing images or hosting a server, and often leaves precise signals to a microcontroller.",
  "Attention aux noms : le Raspberry Pi (ordinateur) et le Raspberry Pi Pico (microcontrôleur) n’ont presque rien en commun.": "Watch the names: the Raspberry Pi (computer) and the Raspberry Pi Pico (microcontroller) have almost nothing in common.",
  "Les cartes du simulateur": "The simulator’s boards",
  "Accepte 5 V": "5 V tolerant",
  "E/S": "I/O",
  "Entrées analogiques": "Analog inputs",
  "Wi-Fi": "Wi-Fi",
  "Pour quoi faire": "What for",
  "Nombres de broches : celles que le simulateur laisse utiliser (sans les broches réservées). Prix : ordres de grandeur pour des clones achetés au Sénégal, très variables selon le vendeur.": "Pin counts: those the simulator lets you use (reserved pins excluded). Prices: rough figures for clones bought in Senegal, varying a lot between sellers.",
  "5 V ou 3,3 V : la règle d’or": "5 V or 3.3 V: the golden rule",
  "L’Uno et la Nano travaillent en 5 V : elles supportent les modules 5 V et pardonnent beaucoup d’erreurs de débutant.": "The Uno and the Nano work at 5 V: they accept 5 V modules and forgive many beginner mistakes.",
  "L’ESP32, le NodeMCU et le Pico travaillent en 3,3 V et aucune de leurs broches n’accepte 5 V : un signal 5 V (écho d’un HC-SR04, sortie d’un module 5 V) peut les détruire. Passez par un pont diviseur (1 kΩ / 2 kΩ) ou un adaptateur de niveau.": "The ESP32, NodeMCU and Pico work at 3.3 V and none of their pins accepts 5 V: a 5 V signal (HC-SR04 echo, output of a 5 V module) can destroy them. Use a voltage divider (1 kΩ / 2 kΩ) or a level shifter.",
  "À l’inverse, un module 3,3 V (BMP280, RC522…) alimenté en 5 V grille : regardez toujours sa tension avant de le brancher.": "Conversely, a 3.3 V module (BMP280, RC522…) powered at 5 V burns out: always check its voltage before connecting it.",
  "Le simulateur signale ces erreurs en rouge dans l’onglet Simulation : essayez avant d’acheter.": "The simulator flags these mistakes in red in the Simulation tab: try before you buy.",
  "Par où commencer ?": "Where to start?",
  "Apprendre": "Learn",
  "Uno, ou Nano pour un montage compact. Des milliers de tutoriels en français ; tous les TP de base de Jollof Studio l’utilisent.": "Uno, or Nano for a compact build. Thousands of tutorials in French; all of Jollof Studio’s basic labs use it.",
  "Connecter": "Connect",
  "ESP32 dès qu’il faut le Wi-Fi ou le Bluetooth (mêmes programmes Arduino, quelques broches à éviter) ; NodeMCU si le budget est très serré.": "ESP32 as soon as you need Wi-Fi or Bluetooth (same Arduino programs, a few pins to avoid); NodeMCU on a very tight budget.",
  "Explorer": "Explore",
  "Pico pour MicroPython et les signaux très précis.": "Pico for MicroPython and very precise signals.",
  "Pour aller plus loin": "Going further",
  "Arduino Uno R4 : même forme et même 5 V que l’Uno, processeur 48 MHz et 32 Ko de mémoire vive ; version WiFi.": "Arduino Uno R4: same shape and same 5 V as the Uno, 48 MHz processor and 32 KB of RAM; WiFi version available.",
  "ESP32-S3 et ESP32-C3 : variantes de l’ESP32 (USB intégré, prix plus bas pour la C3). Importables dans Jollof Studio comme cartes personnelles.": "ESP32-S3 and ESP32-C3: ESP32 variants (built-in USB, lower price for the C3). They can be imported into Jollof Studio as custom boards.",
  "Raspberry Pi Pico 2 (RP2350) : 150 MHz, 520 Ko de mémoire vive et 3 blocs PIO, au lieu de 133 MHz, 264 Ko et 2 PIO pour le Pico.": "Raspberry Pi Pico 2 (RP2350): 150 MHz, 520 KB of RAM and 3 PIO blocks, instead of 133 MHz, 264 KB and 2 PIO for the Pico.",
  "micro:bit : carte d’initiation avec écran de LED, boutons et capteurs intégrés, programmée par blocs ou en Python.": "micro:bit: a beginner board with built-in LED screen, buttons and sensors, programmed with blocks or Python.",
  "Raspberry Pi 4 ou 5 : quand le projet a besoin d’une caméra, de vision par ordinateur ou d’un serveur, associé à une carte ci-dessus pour les capteurs et les moteurs.": "Raspberry Pi 4 or 5: when the project needs a camera, computer vision or a server, paired with one of the boards above for sensors and motors.",
