  "I2C, adresse 0x3C (parfois 0x3D)": "I2C, address 0x3C (sometimes 0x3D)",
  "3,3 à 5 V, ≈ 20 mA": "3.3 to 5 V, ≈ 20 mA",
  "Éclairage": "Backlight",
  "aucun : chaque pixel émet sa propre lumière": "none: each pixel emits its own light",
  "Le programme dessine dans une image en mémoire (1 Ko), puis display() l’envoie à l’écran par I2C.": "The program draws into an image in memory (1 KB), then display() sends it to the screen over I2C.",
  "Afficher des mesures": "Display readings",
