  "Confondre avec un écran 1,3\" (SH1106) : il faut une autre bibliothèque.": "Mixing it up with a 1.3\" display (SH1106): it needs a different library.",
  "16 caractères × 2 lignes, rétroéclairé": "16 characters × 2 lines, backlit",
  "Contrôleurs": "Controllers",
  "HD44780 et adaptateur I2C PCF8574": "HD44780 and PCF8574 I2C adapter",
