  "Plusieurs servos sur le 5 V de la carte : redémarrages.": "Several servos on the board’s 5 V: the board resets.",
  "Forcer en butée : les engrenages en plastique cassent.": "Forcing it against its end stop: the plastic gears break.",
  "Sur ESP32, la bibliothèque Servo standard ne fonctionne pas : utilisez ESP32Servo.": "On ESP32, the standard Servo library doesn’t work: use ESP32Servo.",
  "3 à 6 V": "3 to 6 V",
  "100 à 250 mA à vide, plus de 1 A bloqué": "100 to 250 mA with no load, over 1 A when stalled",
  "par un pilote (L298N, TB6612…)": "through a driver (L298N, TB6612…)",
  "Le courant dans les bobines du rotor crée une force dans le champ des aimants : l’axe tourne. Inverser la polarité inverse le sens ; la tension moyenne, réglée en PWM, fixe la vitesse.": "Current in the rotor coils creates a force in the magnets’ field: the shaft turns. Reversing the polarity reverses the direction; the average voltage, set with PWM, sets the speed.",
  "Roues d’un robot": "Robot wheels",
  "Ventilateur, pompe": "Fan, pump",
  "Le brancher sur une broche de la carte.": "Connecting it directly to a board pin.",
  "Oublier le condensateur de 100 nF entre ses bornes : parasites qui perturbent la carte.": "Forgetting the 100 nF capacitor across its terminals: electrical noise disturbs the board.",
  "L’alimenter avec une pile 9 V : elle s’effondre en quelques minutes.": "Powering it from a 9 V battery: the battery dies within minutes.",
  "unipolaire 4 phases, réduction 1:64": "unipolar, 4-phase, 1:64 gear reduction",
