  "Pilote": "Driver",
  "carte ULN2003 avec 4 LED témoins": "ULN2003 board with 4 indicator LEDs",
  "Les bobines sont alimentées dans un ordre précis : l’aimant du rotor suit le champ, pas après pas. On sait exactement de combien l’axe a tourné, sans capteur.": "The coils are energized in a precise order: the rotor magnet follows the field, step by step. You know exactly how far the shaft has turned, without a sensor.",
