  "Seuil": "Threshold",
  "≈ 0,7 à 1 V": "≈ 0.7 to 1 V",
  "Le courant ne passe que de l’anode vers la cathode (côté bague). Montée en roue libre aux bornes d’une bobine, elle absorbe la pointe de tension produite à la coupure.": "Current only flows from the anode to the cathode (the striped end). Fitted as a flyback diode across a coil, it absorbs the voltage spike produced when the current is cut.",
