  "Ajoutez une carte et des composants : leur schéma s’affiche ici.": "Add a board and some components: their circuit diagram appears here.",
  "Lancez la simulation pour voir le courant circuler.": "Start the simulation to see the current flow.",
  "Points : sens du courant, du + vers le −, plus rapides quand il est plus fort.": "Dots: direction of the current, from + to −, faster when it is stronger.",
