  "La commander directement par une broche : passez par un transistor ou un relais.": "Driving it straight from a pin: use a transistor or a relay.",
  "Oublier la masse commune entre la pile de la pompe et la carte (avec un transistor).": "Forgetting the common ground between the pump’s battery and the board (with a transistor).",
  "2,5 à 3,5 V": "2.5 to 3.5 V",
  "≈ 80 mA": "≈ 80 mA",
