  "L’alimenter en 5 V sans résistance : il s’use vite.": "Powering it with 5 V without a resistor: it wears out quickly.",
  "Le relier directement à une broche : passez par un transistor (avec une diode en parallèle).": "Connecting it straight to a pin: use a transistor (with a diode in parallel).",
  "Alimentation commandée : pilote L298N, transistor ou relais": "Switched power: L298N driver, transistor or relay",
  "Contact de puissance, isolé de la carte": "Power contact, isolated from the board",
