  "l’autre borne doit rejoindre {0}": "the other terminal must go to {0}",
  "à relier à une alimentation : pile, pilote L298N, transistor ou relais": "connect to a power source: battery, L298N driver, transistor or relay",
  "{0} {1} surchargée": "{0} {1} overloaded",
  "Une broche de carte fournit au plus 20 à 40 mA. Un moteur, un ventilateur ou un buzzer en demande bien plus : la sortie chauffe, la tension s’effondre, et la puce peut griller.": "A board pin supplies 20 to 40 mA at most. A motor, a fan or a buzzer needs much more: the output heats up, the voltage collapses, and the chip can burn out.",
  "{0} reçoit trop de tension": "{0} gets too much voltage",
  "Au-delà de sa tension prévue, un moteur tourne trop vite, chauffe et s’use : balais, roulements et bobinage souffrent. Un petit ventilateur ou un vibreur peut griller.": "Above its rated voltage, a motor spins too fast, heats up and wears out: brushes, bearings and windings suffer. A small fan or vibration motor can burn out.",
  "{0} est branché à l’envers": "{0} is wired the wrong way round",
  "Un ventilateur d’ordinateur contient une petite électronique qui ne fonctionne que dans un sens : branché à l’envers, il ne tourne pas (sans dommage, en général).": "A computer fan contains a small circuit that only works one way round: wired backwards, it does not spin (usually without damage).",
  "{0} manque de tension": "{0} lacks voltage",
  "Un servo demande 4,8 à 6 V et jusqu’à 500 mA quand il bouge. En dessous, il tremble, avance par à-coups ou ne bouge plus, et la carte peut redémarrer.": "A servo needs 4.8 to 6 V and up to 500 mA when it moves. Below that, it jitters, moves in jerks or stops moving, and the board may reset.",
  "Commandez la charge par un transistor (NPN, résistance de 1 kΩ sur la base) ou un relais, alimentés par une pile ou le 5 V : la broche ne fait plus que donner l’ordre.": "Drive the load through a transistor (NPN, 1 kΩ resistor on the base) or a relay, powered by a battery or 5 V: the pin then only gives the order.",
  "Alimentez-le sous {0} environ (pile de 4,5 V, 4 piles AA, le 5 V), ou baissez sa tension moyenne en PWM.": "Power it at about {0} (4.5 V battery, 4 AA batteries, 5 V), or lower its average voltage with PWM.",
  "Inversez les deux fils : rouge (+) vers l’alimentation, noir (−) vers la masse ou le transistor.": "Swap the two wires: red (+) to the power supply, black (−) to ground or the transistor.",
  "Alimentez le servo en 5 V (broche 5V de la carte, ou une alimentation 5 V reliée à la masse de la carte).": "Power the servo with 5 V (the board’s 5V pin, or a 5 V supply sharing the board’s ground).",
  "{0} {1} : {2} mA": "{0} {1}: {2} mA",
  "{0} : {1} sur le fil rouge": "{0}: {1} on the red wire",
  "{0} : {1} pour {2} prévus": "{0}: {1} for {2} rated",
  "{0} : {1} entre VCC et GND": "{0}: {1} between VCC and GND",
  "Plus": "Plus",
  "Côté + : vers l’alimentation commandée (sortie de pilote, contact de relais, pile). Un moteur demande des centaines de mA : jamais directement sur une broche de la carte.": "+ side: to the switched supply (driver output, relay contact, battery). A motor draws hundreds of mA: never straight on a board pin.",
  "Moins": "Minus",
  "Côté − : vers la masse, le collecteur d’un transistor ou l’autre sortie du pilote.": "− side: to ground, a transistor’s collector or the driver’s other output.",
  "Borne commune du contact : on y amène le + de l’alimentation de puissance (pile, adaptateur).": "Common terminal of the contact: bring the + of the power supply here (battery, adapter).",
  "Normalement ouvert": "Normally open",
  "Relié à COM seulement quand le relais est collé : la charge (moteur, ventilateur, lampe) s’allume sur commande.": "Connected to COM only while the relay is energized: the load (motor, fan, lamp) turns on when commanded.",
  "Normalement fermé": "Normally closed",
  "Relié à COM au repos, ouvert quand le relais colle.": "Connected to COM at rest, open when the relay is energized.",
  "Ventilateur 5 V (40 mm) : moteur sans balais, son électronique interne impose la polarité : fil rouge au +, noir au −.": "5 V fan (40 mm): brushless motor, its internal circuit sets the polarity: red wire to +, black to −.",
  "Branché à l’envers, il ne tourne pas (sans dommage). Sa vitesse suit la tension : PWM par un transistor ou un pilote.": "Wired backwards, it does not spin (no damage). Its speed follows the voltage: PWM through a transistor or a driver.",
  "Mini pompe à eau immergée 5 V : un petit moteur à courant continu entraîne une turbine.": "Mini submersible water pump 5 V: a small DC motor drives an impeller.",
  "Toujours immergée : à sec, elle s’use en quelques minutes. Commandée par un transistor ou un relais, avec une pile ou un adaptateur 5 V.": "Always submerged: running dry wears it out in minutes. Controlled by a transistor or a relay, with a battery or a 5 V adapter.",
  "Moteur vibreur (pièce de 10 mm) : une masse décentrée sur l’axe fait vibrer, comme dans un téléphone.": "Vibration motor (10 mm coin): an off-centre weight on the shaft makes it vibrate, like in a phone.",
  "3 V nominal, environ 80 mA : par un transistor, jamais directement sur une broche.": "3 V rated, about 80 mA: through a transistor, never straight on a pin.",
