  "Résistance 330 Ω": "330 Ω resistor",
  "Transistor NPN PN2222A": "PN2222A NPN transistor",
  "Adaptateur de niveau 3,3 V ↔ 5 V": "3.3 V ↔ 5 V level shifter",
