  // licence et crédits
  "Licence de Jollof Studio": "Jollof Studio licence",
  "Jollof Studio est un logiciel libre : vous pouvez le redistribuer et le modifier selon les termes de la licence publique générale GNU Affero (AGPL), version 3 ou ultérieure, avec les conditions supplémentaires ci-dessous.": "Jollof Studio is free software: you can redistribute it and modify it under the terms of the GNU Affero General Public License (AGPL), version 3 or later, with the additional terms below.",
  "Toute copie, version modifiée ou œuvre fondée sur Jollof Studio garde la mention « {0} » et affiche « Basé sur Jollof Studio par Mamadou Sarr », avec un lien vers le projet d’origine (AGPL, section 7 b).": "Every copy, modified version or work based on Jollof Studio keeps the notice “{0}” and displays “Based on Jollof Studio by Mamadou Sarr”, with a link to the original project (AGPL, section 7 b).",
  "Une version modifiée se présente comme différente de l’original et porte un autre nom ; la licence ne donne aucun droit sur le nom « Jollof Studio », son logo ou ses icônes (section 7 c et e).": "A modified version presents itself as different from the original and uses another name; the licence grants no right to the name “Jollof Studio”, its logo or its icons (section 7 c and e).",
  "Une version modifiée utilisée par d’autres, même seulement à travers un réseau (serveur d’école, site web), doit leur proposer son code source complet (section 13).": "A modified version used by others, even only over a network (school server, website), must offer them its complete source code (section 13).",
  "Ce programme est distribué dans l’espoir qu’il sera utile, mais SANS AUCUNE GARANTIE, ni explicite ni implicite, y compris de qualité marchande ou d’adéquation à un usage particulier.": "This program is distributed in the hope that it will be useful, but WITHOUT ANY WARRANTY, express or implied, including of merchantability or fitness for a particular purpose.",
  "Code source : {0}. Texte de la licence : fichiers LICENSE et NOTICE.md du dépôt.": "Source code: {0}. Licence text: the LICENSE and NOTICE.md files of the repository.",
  "Une licence commerciale est proposée à qui ne peut pas respecter l’AGPL (garder ses modifications privées, intégrer Jollof Studio à un produit fermé) : voir COMMERCIAL.md.": "A commercial licence is available to anyone who cannot meet the AGPL (to keep their changes private, or to build Jollof Studio into a closed product): see COMMERCIAL.md.",
  "{0} paquets JavaScript et {1} bibliothèques Rust, tous compatibles avec l’AGPL et avec la licence commerciale. Principaux :": "{0} JavaScript packages and {1} Rust libraries, all compatible with the AGPL and with the commercial licence. Main ones:",
  "Répartition par licence :": "By licence:",
  "Liste complète : fichier THIRD_PARTY.md du dépôt (inventaire du {0}). Textes des licences dans le dossier licenses/ de l’application.": "Full list: the THIRD_PARTY.md file of the repository (inventory of {0}). Licence texts in the app’s licenses/ folder.",
  "La licence de Jollof Studio, puis les modèles 3D et les bibliothèques tierces livrés avec l’application.": "Jollof Studio’s licence, then the 3D models and third-party libraries shipped with the app.",
  // mode fidèle (vrai programme émulé)
