  "LED RGB à anode commune (réglage par défaut de Wokwi) : la bibliothèque a une LED à cathode commune, COM passe à la masse et la logique du programme s’inverse": "Common-anode RGB LED (Wokwi's default): the library has a common-cathode LED, so COM goes to ground and the program's logic is inverted",
