  "Débutant : interpréteur instantané, pas à pas. Fidèle : le vrai programme compilé par arduino-cli tourne sur un processeur émulé (application installée). MicroPython (Pico) : programme en Python, sur le vrai MicroPython émulé.": "Beginner: instant interpreter, step by step. Faithful: the real program compiled by arduino-cli runs on an emulated processor (installed app). MicroPython (Pico): a Python program, on real emulated MicroPython.",
