  "Dans au moins un état, le MOSFET dépasse son courant de drain.": "In at least one state, the MOSFET exceeds its drain current.",
  "Au-delà de 47 A (33 A à 100 °C), ses connexions internes et sa puce sont détruites.": "Beyond 47 A (33 A at 100 °C), its internal connections and its die are destroyed.",
  "Réduisez la charge ou prenez un MOSFET plus puissant, sur radiateur.": "Reduce the load or use a more powerful MOSFET, on a heatsink.",
  "Dans au moins un état, la grille du MOSFET reçoit plus de ±16 V par rapport à la source.": "In at least one state, the MOSFET gate receives more than ±16 V relative to the source.",
  "L’isolant très fin de la grille claque : le MOSFET est détruit, souvent en court-circuit.": "The very thin gate insulation breaks down: the MOSFET is destroyed, often shorted.",
  "Commandez la grille avec la tension logique de la carte (3,3 ou 5 V), jamais avec l’alimentation de la charge.": "Drive the gate with the board's logic voltage (3.3 or 5 V), never with the load supply.",
  "Dans au moins un état, la tension drain-source dépasse 55 V.": "In at least one state, the drain-source voltage exceeds 55 V.",
  "Le MOSFET entre en avalanche et se détruit.": "The MOSFET goes into avalanche and is destroyed.",
  "Alimentez la charge sous moins de 55 V, et placez une diode de roue libre aux bornes d’une charge à bobine.": "Supply the load with less than 55 V, and put a flyback diode across a coil load.",
  "Dans au moins un état, la sortie du NE555 fournit ou absorbe plus de 200 mA.": "In at least one state, the NE555 output sources or sinks more than 200 mA.",
  "Son étage de sortie chauffe et se détruit au-delà de 225 mA.": "Its output stage heats up and is destroyed beyond 225 mA.",
  "Augmentez la résistance de la charge, ou commandez-la par un transistor (MOSFET IRLZ44N) piloté par la sortie.": "Increase the load resistance, or drive the load through a transistor (IRLZ44N MOSFET) controlled by the output.",
  "Dans au moins un état, la bobine est traversée par plus que son courant assigné.": "In at least one state, the coil carries more than its rated current.",
  "Son fil chauffe (plus de 35 °C d’échauffement à 76 mA) ; au-delà de 110 mA son noyau sature : l’inductance chute et le montage ne se comporte plus comme prévu.": "Its wire heats up (more than 35 °C rise at 76 mA); beyond 110 mA its core saturates: the inductance drops and the circuit no longer behaves as designed.",
  "Ajoutez une résistance en série ou prenez une bobine prévue pour plus de courant.": "Add a series resistor or use a coil rated for more current.",
  "Dans au moins un état, une entrée de l’ampli-op dépasse sa plage de mode commun (VCC − 1,5 V pour le LM358).": "In at least one state, an op-amp input exceeds its common-mode range (VCC − 1.5 V for the LM358).",
  "Au-delà, l’étage d’entrée ne suit plus : la sortie se fige ou s’écrête, le gain calculé n’est plus vrai.": "Beyond it, the input stage stops following: the output freezes or clips, the calculated gain is no longer true.",
  "Gardez les entrées entre la masse et VCC − 1,5 V : alimentez l’ampli plus haut, ou abaissez le signal (pont diviseur).": "Keep the inputs between ground and VCC − 1.5 V: power the amplifier higher, or lower the signal (voltage divider).",
  "Dans au moins un état, une entrée de l’ampli-op descend sous −0,3 V.": "In at least one state, an op-amp input goes below −0.3 V.",
  "Les diodes de protection de l’entrée conduisent : l’ampli peut se bloquer ou être détruit.": "The input protection diodes conduct: the amplifier may latch up or be destroyed.",
  "En alimentation simple, gardez le signal au-dessus de la masse : ajoutez un décalage (générateur, pont diviseur).": "On a single supply, keep the signal above ground: add an offset (generator, voltage divider).",
  "Dans au moins un état, le MOSFET dissipe trop sans radiateur.": "In at least one state, the MOSFET dissipates too much without a heatsink.",
  "Il perd RDS(on) × I² en chaleur : 1,4 W porte la puce à 125 °C, 2,2 W à 175 °C, sa limite. Une grille à 3,3 V le rend moins passant, donc plus chaud.": "It loses RDS(on) × I² as heat: 1.4 W takes the die to 125 °C, 2.2 W to 175 °C, its limit. A 3.3 V gate turns it on less, so it runs hotter.",
  "Réduisez le courant, commandez la grille en 5 V, ou vissez un radiateur sur la languette.": "Reduce the current, drive the gate at 5 V, or screw a heatsink onto the tab.",
